import java.util.LinkedHashMap;
import java.util.Map;

public class HttpRequestBuilderTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String esc(String text) {
        if (text == null) {
            return "null";
        }
        return text.replace("\r", "\\r").replace("\n", "\\n");
    }

    static String build(String host, String path, Map<String, String> headers) {
        try {
            String result = HttpRequestBuilder.buildGet(host, path, headers);
            return result == null ? "" : result;
        } catch (Throwable t) {
            return "threw " + t.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        String bare = build("example.com", "/index.html", new LinkedHashMap<String, String>());
        check("no headers", esc("GET /index.html HTTP/1.1\r\nHost: example.com\r\n\r\n"), esc(bare));

        Map<String, String> one = new LinkedHashMap<>();
        one.put("Accept", "text/html");
        String single = build("example.org", "/", one);
        check("one header", esc("GET / HTTP/1.1\r\nHost: example.org\r\nAccept: text/html\r\n\r\n"), esc(single));

        Map<String, String> many = new LinkedHashMap<>();
        many.put("User-Agent", "study-client/1.0");
        many.put("Connection", "close");
        many.put("Accept", "*/*");
        String sorted = build("example.net", "/api/data", many);
        check("headers are sorted by key",
                esc("GET /api/data HTTP/1.1\r\nHost: example.net\r\n"
                        + "Accept: */*\r\nConnection: close\r\nUser-Agent: study-client/1.0\r\n\r\n"),
                esc(sorted));

        String query = build("example.com", "/search?q=java", null);
        check("null header map, path with query",
                esc("GET /search?q=java HTTP/1.1\r\nHost: example.com\r\n\r\n"), esc(query));

        check("request ends with a blank line", Boolean.TRUE, Boolean.valueOf(sorted.endsWith("\r\n\r\n")));
        check("no bare newlines are used", Boolean.FALSE,
                Boolean.valueOf(sorted.replace("\r\n", "").contains("\n")));
        check("sorted request has 6 CRLF line endings", 6,
                (sorted.length() - sorted.replace("\r\n", "").length()) / 2);

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

